insert into public.dealerships (slug, name, phone, email, address, maps_url, hours, socials)
select 'autolux', 'AutoLux', '+7 727 555 01 48', 'concierge@autolux.example',
  '{"en":{"line1":"12 Prestige Avenue","line2":"Almaty, Kazakhstan 050000"},"ru":{"line1":"пр. Престиж, 12","line2":"Алматы, Казахстан 050000"},"kk":{"line1":"Престиж даңғылы, 12","line2":"Алматы, Қазақстан 050000"}}'::jsonb,
  'https://maps.google.com/?q=Prestige+Avenue+12+Almaty', '{"weekdays":"9:00 – 19:00","saturday":"10:00 – 18:00","sunday":"11:00 – 16:00"}'::jsonb, '[{"label":"Instagram","href":"https://www.instagram.com/"},{"label":"LinkedIn","href":"https://www.linkedin.com/"},{"label":"YouTube","href":"https://www.youtube.com/"}]'::jsonb
where not exists (select 1 from public.dealerships where slug = 'autolux');

